// Progressive web app controls for The Bukit Besi Tools.
(function () {
  'use strict';
  if (window.bukitToolsPwa) return;
  window.bukitToolsPwa = true;
  if (!('serviceWorker' in navigator) || !window.isSecureContext) return;

  const installButton = document.getElementById('pwaInstall');
  const notice = document.getElementById('pwaNotice');
  const message = document.getElementById('pwaMessage');
  const updateButton = document.getElementById('pwaUpdate');
  const closeButton = document.getElementById('pwaClose');
  const openButton = document.getElementById('pwaOpen');
  if (!installButton || !notice || !message || !updateButton || !closeButton || !openButton) return;
  const standalone = window.matchMedia('(display-mode: standalone)');
  let deferredPrompt = null;
  let registration = null;
  let reloadAfterUpdate = false;
  let lastUpdateCheck = 0;

  const MS = {
    'You are offline. Saved pages and calculators still work; Blogger tools need internet.': 'Anda di luar talian. Halaman dan kalkulator yang disimpan masih berfungsi; alat di Blogger memerlukan internet.',
    'An updated tools directory is ready.': 'Versi baharu direktori alat sudah sedia.',
    'Updating the directory...': 'Mengemas kini...',
    'Use your browser menu to choose Install app or Add to Home Screen. On iPhone or iPad, use the Share menu in Safari. Availability varies by browser.': 'Gunakan menu pelayar dan pilih Pasang aplikasi atau Tambah ke Skrin Utama. Di iPhone atau iPad, gunakan menu Kongsi dalam Safari.',
    'Installation was unavailable. Try the Install app or Add to Home Screen option in your browser.': 'Pemasangan tidak tersedia. Cuba pilihan Pasang aplikasi atau Tambah ke Skrin Utama dalam pelayar anda.',
    'This tool opens on Blogger and needs internet. You can still browse the saved directory.': 'Alat ini dibuka di Blogger dan memerlukan internet. Anda masih boleh melayari direktori yang disimpan.'
  };
  const t = text => (document.documentElement.lang === 'ms' && MS[text]) || text;

  function show(text, offerUpdate = false, toolUrl = null) {
    openButton.hidden = !toolUrl;
    if (toolUrl) openButton.href = toolUrl;
    else openButton.removeAttribute('href');
    message.textContent = t(text);
    updateButton.hidden = !offerUpdate;
    notice.hidden = false;
  }
  function hide() {
    notice.hidden = true;
    message.textContent = '';
    updateButton.hidden = true;
    openButton.hidden = true;
    openButton.removeAttribute('href');
  }
  function installVisibility() {
    installButton.hidden = standalone.matches || navigator.standalone === true;
  }
  function networkStatus() {
    if (!navigator.onLine) {
      show('You are offline. Saved pages and calculators still work; Blogger tools need internet.');
    } else if (registration && registration.waiting) {
      show('An updated tools directory is ready.', true);
    } else {
      hide();
    }
  }
  function offerUpdate(worker = registration && registration.waiting) {
    // installed state can fire before registration.waiting is exposed.
    if (worker && navigator.serviceWorker.controller) {
      show('An updated tools directory is ready.', true);
    }
  }
  closeButton.addEventListener('click', hide);
  updateButton.addEventListener('click', () => {
    if (!registration || !registration.waiting) return;
    reloadAfterUpdate = true;
    updateButton.disabled = true;
    message.textContent = t('Updating the directory...');
    registration.waiting.postMessage({ type: 'SKIP_WAITING' });
  });
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    // First installation and updates in other tabs must not reload this page.
    if (!reloadAfterUpdate) return;
    reloadAfterUpdate = false;
    window.location.reload();
  });
  window.addEventListener('beforeinstallprompt', event => {
    event.preventDefault();
    deferredPrompt = event;
    installVisibility();
  });
  installButton.addEventListener('click', async () => {
    if (!deferredPrompt) {
      show('Use your browser menu to choose Install app or Add to Home Screen. On iPhone or iPad, use the Share menu in Safari. Availability varies by browser.');
      return;
    }
    const prompt = deferredPrompt;
    deferredPrompt = null;
    installButton.disabled = true;
    try {
      await prompt.prompt();
      await prompt.userChoice;
    } catch {
      show('Installation was unavailable. Try the Install app or Add to Home Screen option in your browser.');
    } finally {
      installButton.disabled = false;
    }
  });
  window.addEventListener('appinstalled', () => {
    deferredPrompt = null;
    installButton.hidden = true;
    hide();
  });
  standalone.addEventListener('change', installVisibility);
  window.addEventListener('online', networkStatus);
  window.addEventListener('offline', networkStatus);
  document.addEventListener('click', event => {
    if (navigator.onLine || event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
    const link = event.target.closest && event.target.closest('a.card-link');
    if (link && new URL(link.href).origin !== window.location.origin) {
      event.preventDefault();
      // Connection status is a hint, so visitors may still try the original link.
      show('This tool opens on Blogger and needs internet. You can still browse the saved directory.', false, link.href);
    }
  });

  async function register() {
    try {
      registration = await navigator.serviceWorker.register('/sw.js', { scope: '/', updateViaCache: 'none' });
      lastUpdateCheck = Date.now();
      offerUpdate();
      registration.addEventListener('updatefound', () => {
        const worker = registration.installing;
        if (!worker) return;
        worker.addEventListener('statechange', () => {
          if (worker.state === 'installed') offerUpdate(worker);
        });
      });
    } catch (error) {
      console.warn('Offline access could not be enabled.', error);
    }
  }
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible' || !navigator.onLine || !registration) return;
    if (Date.now() - lastUpdateCheck < 60 * 60 * 1000) return;
    lastUpdateCheck = Date.now();
    registration.update().catch(() => {});
  });
  installVisibility();
  networkStatus();
  function afterLoad() {
    if ('requestIdleCallback' in window) requestIdleCallback(register, { timeout: 2000 });
    else setTimeout(register, 0);
  }
  if (document.readyState === 'complete') afterLoad();
  else window.addEventListener('load', afterLoad, { once: true });
})();
